-- ==========================================================================
-- DIGEST-COPY RECUT: gasprocessing, question text only.
--
-- WHY. The live bank tells learners what "the digest" prints, points at numbered
-- SECTIONs of it, or names the authors' generator. The digest is the course
-- authors' internal reference file and no learner can see it. Each row below is
-- rewritten to name what the learner has: the course, the lesson, the lab or the
-- engine. Nothing else moves: no answer index, no option order, no ord, no
-- module key, no scope, no row count. Option lengths keep their rank.
--
-- SOURCE of the new text: the regenerated bank JSON under tools/course-banks/gasprocessing, built from its committed .py sources.
-- Rows: 21 (beginner 4, advanced 17).
--
-- GUARDS. Each row is addressed by (app_slug, tier, scope, module_key, ord) and must
-- carry EITHER its published text exactly (then it is updated) OR the recut text
-- exactly (already applied, left alone). Anything else raises and the whole
-- transaction rolls back. Every update must touch exactly 1 row, and the course
-- must still hold its question count at the end. SAFE TO RE-RUN.
-- Published text was read from a replay of every question migration at origin/main,
-- FC9's recut (#181) and the B3 engine-strings recut (#184) included, so a row either
-- of those rewrote is expected to carry THEIR text: apply them first.
-- (docs/digest-recut/RECUT-gasprocessing.json carries OLD and NEW for every row).
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- beginner final ord 7
  select case
           when prompt = 'Why does this module export every constant it uses under a name?' and options = '["So the published cases can vary each one of them in turn and record exactly what moved.", "So a reader can point at the number rather than infer it from an answer.", "So the studio can offer every one of them as a box on the page.", "So a gate can re-derive each one from the publication it came from."]'::jsonb and answer_index = 1 and explanation is not distinct from 'Naming a constant is what makes the difference between the three kinds visible at all, and it is what lets the digest measure four of them back out of return values.' then 'old'
           when prompt = 'Why does this module export every constant it uses under a name?' and options = '["So the published cases can vary each one of them in turn and record exactly what moved.", "So a reader can point at the number rather than infer it from an answer.", "So the studio can offer every one of them as a box on the page.", "So a gate can re-derive each one from the publication it came from."]'::jsonb and answer_index = 1 and explanation is not distinct from 'Naming a constant is what makes the difference between the three kinds visible at all, and it is what lets the course measure four of them back out of return values.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'gasprocessing' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 7;
  if v_state is null then raise exception 'digest-copy recut, gasprocessing refused: no row for beginner final ord 7'; end if;
  if v_state = 'other' then raise exception 'digest-copy recut, gasprocessing refused: beginner final ord 7 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Why does this module export every constant it uses under a name?', options = '["So the published cases can vary each one of them in turn and record exactly what moved.", "So a reader can point at the number rather than infer it from an answer.", "So the studio can offer every one of them as a box on the page.", "So a gate can re-derive each one from the publication it came from."]'::jsonb, explanation = 'Naming a constant is what makes the difference between the three kinds visible at all, and it is what lets the course measure four of them back out of return values.'
     where app_slug = 'gasprocessing' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 7;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, gasprocessing refused: beginner final ord 7 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

